import os
for root,dirs,files in os.walk('studies'):
 for f in files: print(os.path.join(root,f))

import glob,gzip
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for l in h:
   if any(x in l.lower() for x in ['processing','normaliz','!sample_description','!series_summary','!series_overall_design','!sample_supplementary','!series_supplementary']):print(l[:10000].rstrip())

import gzip,glob,csv,io,pandas as pd,numpy as np
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\n',f)
 s=gzip.open(f,'rt').read()
 for l in s.splitlines():
  if 'processing' in l or l.startswith('!Series_supplementary_file'):
   print(l.split('\t')[0],set(next(csv.reader([l],delimiter='\t'))[1:]))
 data=s.split('!series_matrix_table_begin')[1].split('!series_matrix_table_end')[0].strip()
 df=pd.read_csv(io.StringIO(data),sep='\t',index_col=0)
 print('shape',df.shape)
 if df.size:
  a=df.to_numpy().astype(float);print(df.iloc[:3,:3]);print('quantiles',np.nanquantile(a,[0,.01,.25,.5,.75,.99,1]));print('integer frac',np.nanmean(a==np.round(a)))

